resp = requests.get(self.url, params={'ticker': 'BTC-EUR'}, headers={'Authorization': self.authorization, 'Content-Type': 'text/xml'})
if resp.status_code != 200:
  raise UserError(resp.text)

for asset in self.env['investment.asset'].search([('endpoint_id', '=', self.id)]):
  _logger.info("Run integration on %s", asset.name)
  self.produce(variables={'asset': asset})

resp = requests.request(
  self.http_method,
  self.location,
  headers={
    'Authorization': self.authorization,
    'Content-Type': 'text/xml',
  },
  params={
    'ticker': asset.ticker
  },
  timeout=10,
)
if resp.status_code != 200:
  raise UserError(resp.text)

data = resp.content
obj = lxml.etree.fromstring(data)
